UPDATE companies SET description='Idaho Shirtsmith Custom Apparel & Embroidery was founded in 2022 in Nampa, Idaho. The business is led by Zack and his team, providing custom apparel and embroidery services to local companies.

The shop offers screen printing, digital transfer printing, commercial embroidery, and laser‑engraved leather patches, along with promotional products such as bags and drinkware. Since opening, the company has completed over 1,000 custom orders for more than 100 businesses.

Its customer base includes Idaho businesses across various sectors; one noted client is Metalhead Mechanical, a mechanical contractor that praised the team’s work. The company emphasizes a three‑step process: request a quote, approve a design, and receive finished apparel on schedule.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom apparel", "Screen printing", "Digital transfer printing", "Embroidery", "Premium commercial embroidery", "Laser engraved leather patches", "Promotional products (bags, drinkware)"], "industries": ["Idaho businesses", "Mechanical contractors"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded 2022 -> db", "Headquarters Nampa, Idaho -> db", "Services: custom apparel, screen printing, embroidery, laser engraved leather patches, promotional products -> /", "1000+ custom orders completed, 100+ happy businesses -> /", "Customer example: Metalhead Mechanical -> /", "Process: request quote, approve design, print & deliver -> /", "Fast quotes, design collaboration, on-time delivery -> /", "Uses and recommends top brands -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "CUSTOM APPAREL & EMBROIDERY SERVICES", "founded_year": "2022", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='idaho-shirtsmith-custom-apparel-embroidery' AND approved AND profile IS NULL;
UPDATE companies SET description='Idaho Supreme Potatoes operates in Firth, Idaho, where it began as a fresh potato packing operation in 1967. The facility added dehydration capacity in 1969 and grew into one of North America''s potato dehydration plants. In 2018, Idaho Pacific Holdings acquired the company and continues its tradition of supplying dehydrated potato products worldwide.

The plant produces dehydrated potato flakes, flour, slices, dices, and shreds/hash browns, with ingredient specifications ranging from whole flake to finely milled flour, full-cook to low-leach, and additive-free clean-label options. Foodservice lines include blended or agglomerated mashed potato mixes, scalloped and au gratin casseroles, and seasoned or unseasoned hash browns. An in-house R&D team develops custom formulations. Packaging runs from poly pouches, gabled cartons, and #10 tins to kraft bags, bulk sacks, and bulk rail or truck loads, with private-label options for foodservice and retail.

The facility sources Russet varieties such as Burbank, Norkotah, and Ranger from Idaho''s Snake River Plain.

The operation highlights its diverse production capabilities, custom specification development, private-label packaging, bulk rail and truck logistics, and certifications under a GFSI-benchmarked standard, Kosher (OU), and Halal (IFANCA).', certifications=ARRAY['GFSI approved standard','Kosher (Orthodox Union)','Halal (IFANCA)']::text[], profile='{"capabilities": ["Potato dehydration", "Flake production", "Flour milling", "Slicing", "Dicing", "Shredding/Hash brown production", "Blending", "Agglomeration", "Research & development for custom formulations", "Packaging: poly pouches", "Packaging: gabled cartons", "Packaging: #10 tins", "Packaging: kraft bags", "Packaging: polyethylene bulk sacks", "Bulk rail shipping", "Bulk truck shipping", "Private labeling"], "industries": ["Foodservice", "Retail", "Food ingredient manufacturing"], "materials": ["Potatoes (Russet varieties: Burbank, Norkotah, Ranger)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Diverse dehydrated potato product line (flakes, flour, slices, dices, shreds)", "Custom ingredient specifications (full cook, low leach, clean label)", "In-house R&D for custom formulations", "Private labeling for foodservice and retail", "Bulk rail and truck shipping capabilities", "GFSI, Kosher (OU), and Halal (IFANCA) certifications"], "facts_used": ["Located in Firth, Idaho -> /", "Started as fresh potato packing operation in 1967 -> /", "Expanded into potato dehydration in 1969 -> /", "Became one of the leading potato dehydration facilities in North America -> /", "Acquired by Idaho Pacific Holdings in 2018 -> /", "Manufactures dehydrated potato flakes, flour, slices, dices, shreds/hash browns -> /", "Offers ingredient specifications: whole flake, finely milled flakes/flours, full cook, low leach, additive free/clean label -> /", "Foodservice products: mashed potato mixes (blended/agglomerated), scalloped and au gratin casseroles, seasoned/unseasoned hashbrowns -> /", "In-house R&D te