ion for the custom sheet extrusion industry", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='impact-plastics' AND approved AND profile IS NULL;
